h0 = sob_top("HTL", 0); r1 = RISK["S01 HTL base"]; r54 = RISK["S54 HTL NZ 2050"]; a26 = fmin("2026", "mfsp"); a50 = fmin("2050_NZ", "mfsp"); mh = MLM["HTL"]["Neural network (MLP 64-64)"]
